// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address actor, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);
        vm.assume(actor != address(this));

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(actor);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || address(c).balance == balanceBefore);
    }
}
